{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is SLOC?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "SLOC stands for Source Lines of Code. It is a software metric used to measure the size of a program by counting lines in its source code. OctoCounts reports total lines, code lines, comment lines, and blank lines per language, plus aggregate totals across the repository."
      }
    },
    {
      "@type": "Question",
      "name": "Why use OctoCounts instead of cloning and running tokei locally?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "OctoCounts is faster for large repositories because it downloads a compressed archive tarball rather than a full git clone with history. It also caches results by commit SHA, so any repeated analysis of the same commit returns instantly with zero re-processing."
      }
    },
    {
      "@type": "Question",
      "name": "Is OctoCounts free to use?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. OctoCounts is completely free to use for public GitHub repositories. No account or authentication is required."
      }
    },
    {
      "@type": "Question",
      "name": "What programming languages does OctoCounts support?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "OctoCounts uses tokei for language detection, which supports over 200 programming languages and file types including Rust, Python, JavaScript, TypeScript, Go, Java, C, C++, Ruby, Swift, Kotlin, and many more."
      }
    },
    {
      "@type": "Question",
      "name": "Can I export the source line count results?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. OctoCounts supports three export formats: plain text (copy to clipboard), JSON (full report with per-language stats), and a shareable PNG card showing the language breakdown at 1200x630 resolution."
      }
    },
    {
      "@type": "Question",
      "name": "Does OctoCounts support private repositories?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "OctoCounts currently supports public GitHub repositories only. Private repositories require authentication which is not yet supported."
      }
    }
  ]
}
